# Un bloc : TYPE  "LABEL1"  "LABEL2"  { ... arguments ... }
resource "aws_instance" "web" {
  ami           = "ami-123456"       # argument : clé = valeur
  instance_type = "t3.micro"

  tags = {                            # une valeur peut être une map
    Name        = "serveur-web"
    Environment = "prod"
  }
}

# Un bloc de configuration Terraform lui-même
terraform {
  required_version = ">= 1.5"
}

locals {
  # transformer une liste en map indexée par nom
  users_by_name = { for u in var.users : u.name => u }

  # filtrer puis transformer
  active_emails = [for u in var.users : u.email if u.active]
}

# Splat : extraire un attribut de toutes les instances d'une ressource
output "all_ips" {
  value = aws_instance.web[*].private_ip   # [*] = splat
}

resource "aws_security_group" "web" {
  name = "web"

  dynamic "ingress" {
    for_each = var.allowed_ports        # ex. [80, 443]
    content {
      from_port   = ingress.value
      to_port     = ingress.value
      protocol    = "tcp"
      cidr_blocks = ["0.0.0.0/0"]
    }
  }
}
# Génère un bloc ingress par port de la liste.
